async function installDemoEvent({openAfter=true,silent=false}={}){
  const button=document.getElementById('kx-install-demo-event');if(button){button.disabled=true;button.textContent='Preparando evento de ejemplo…';}
  try{
    const seeded=await repos.kombaxEvents.seedDemoEvent();const eventId=seeded?.event_id;if(!eventId)throw new Error('No se pudo crear el evento de ejemplo.');
    const existing=await repos.kombaxEvents.media(eventId).catch(()=>[]);const existingIds=new Set((existing||[]).filter(x=>x.estado!=='retirado').map(x=>String(x.id)));
    for(let i=0;i<DEMO_EVENT_ASSETS.length;i++){
      const asset=DEMO_EVENT_ASSETS[i];if(existingIds.has(asset.id))continue;
      if(button)button.textContent=`Subiendo álbum ${i+1}/${DEMO_EVENT_ASSETS.length}…`;
      const file=await repos.kombaxEvents.demoAssetFile(`./assets/demo-events/noche-impacto-barcelona/${asset.file}`,{name:asset.file,type:'image/webp'});
      await repos.kombaxEvents.uploadDemoMedia(eventId,file,{media_id:asset.id,titulo:asset.titulo,descripcion:`${asset.file==='fight-card-full.webp'?FIGHT_CARD_POSTER_MARKER+' ':''}Contenido ilustrativo para validación y presentación comercial.`,momento:asset.momento,destacado:asset.destacado===true,orden:asset.orden});
    }
    if(!silent)toast('Evento de ejemplo instalado como un KOMBAX Evento real.');await loadDiscovery({append:false});if(openAfter)await openEvent(eventId);
  }catch(error){if(!silent)toast(error?.message||'No se pudo instalar el evento de ejemplo.','error');else console.warn('Demo Event media bootstrap:',error);}
  finally{if(button){button.disabled=false;button.innerHTML=`${icon('sparkles',{size:15})} Instalar / actualizar ejemplo`;}}
}

