async function maybeAutoInstallDemoAlbum(){
  if(demoAutoInstallStarted||!(state.session?.platform_admin===true||state.session?.platform_level==='owner'))return;
  const demo=cached.find(x=>x.slug===DEMO_EVENT_SLUG);if(!demo)return;
  demoAutoInstallStarted=true;
  const rows=await repos.kombaxEvents.media(demo.id).catch(()=>[]);
  const active=(rows||[]).filter(x=>x.estado!=='retirado');
  if(active.length>=DEMO_EVENT_ASSETS.length)return;
  await installDemoEvent({openAfter:false,silent:true});
}

async function maybeAutoInstallUrbanWarriorsJiuJitsuAlbum(){
  if(urbanJiuJitsuAutoInstallStarted||!(state.session?.platform_admin===true||state.session?.platform_level==='owner'))return;
  urbanJiuJitsuAutoInstallStarted=true;
  const demo=cached.find(x=>x.slug===URBAN_WARRIORS_JIUJITSU_DEMO_SLUG);
  if(!demo){await installUrbanWarriorsJiuJitsuDemoEvent({openAfter:false,silent:true});return;}
  const rows=await repos.kombaxEvents.media(demo.id).catch(()=>[]);
  const active=(rows||[]).filter(x=>x.estado!=='retirado');
  if(active.length>=URBAN_WARRIORS_JIUJITSU_DEMO_ASSETS.length)return;
  await installUrbanWarriorsJiuJitsuDemoEvent({openAfter:false,silent:true});
}

function tabsHtml(){return `<div class="kx-events-toolbar"><label class="kx-events-search">${icon('search',{size:17})}<input id="kx-events-query" value="${esc(filters.query)}" placeholder="Buscar evento, ciudad, recinto u organizador" autocomplete="off"></label><div class="kx-events-state-tabs"><button type="button" data-kx-state="" class="${!filters.estado?'active':''}">Todos</button><button type="button" data-kx-state="phase:ahora" class="${filters.estado==='phase:ahora'?'active':''}">En directo</button><button type="button" data-kx-state="phase:proximo" class="${filters.estado==='phase:proximo'?'active':''}">Próximos</button><button type="button" data-kx-state="inscripciones_abiertas" class="${filters.estado==='inscripciones_abiertas'?'active':''}">Inscripciones</button><button type="button" data-kx-state="phase:finalizado" class="${filters.estado==='phase:finalizado'?'active':''}">Resultados</button></div></div>`;}

function invitationHtml(){if(!invitations.length)return '';return `<section class="kx-event-invites"><div class="kx-events-section-head"><div><span>COLABORACIÓN</span><h2>Invitaciones de organización</h2></div><p>La gestión compartida solo se activa después de que la entidad acepte la invitación y tenga permisos para organizar.</p></div><div class="kx-event-invite-grid">${invitations.map(x=>`<article class="kx-event-invite"><div><small>${esc(ROLE_META[x.rol]?.label||x.rol)}</small><strong>${esc(x.evento_nombre)}</strong><span>${esc(x.identidad_nombre)} · ${esc(rangeLabel({fecha_inicio:x.evento_fecha}))}</span></div><div><button class="btn btn-ghost btn-sm" data-kx-invite="${esc(x.id)}" data-answer="0">Rechazar</button><button class="btn btn-primary btn-sm" data-kx-invite="${esc(x.id)}" data-answer="1">Aceptar</button></div></article>`).join('')}</div></section>`;}
function discoveryRequest(){
  const phase=filters.estado.startsWith('phase:')?filters.estado.slice(6):'';
  const estado=phase?'':filters.estado;
  return {query:filters.query.trim(),tipo:filters.tipo||'',estado:estado||'',phase};
}
async function loadDiscovery({append=false}={}){
  const seq=++discoveryRequestSeq;
  if(!append){discoveryCursor=null;discoveryHasMore=false;}
  discoveryLoading=true;
  try{
    const request=discoveryRequest();
    const [page,promoted]=await Promise.all([
      repos.kombaxEvents.listPage({...request,cursor:append?discoveryCursor:null,limit:EVENT_DISCOVERY_PAGE_SIZE}),
      !append&&!request.query&&!request.tipo&&!request.estado&&!request.phase?repos.kombaxEvents.promoted(6):Promise.resolve([])
    ]);
    if(seq!==discoveryRequestSeq)return;
    const rows=(Array.isArray(page?.items)?page.items:[]).filter(event=>!isInternalDemoEvent(event));
    if(append){const seen=new Set(cached.map(x=>String(x.id)));cached=[...cached,...rows.filter(x=>!seen.has(String(x.id)))];}
    else{const promotedRows=(Array.isArray(promoted)?promoted:[]).filter(event=>!isInternalDemoEvent(event));const seen=new Set(promotedRows.map(x=>String(x.id)));cached=[...promotedRows,...rows.filter(x=>!seen.has(String(x.id)))];}
    discoveryCursor=page?.next_cursor||null;discoveryHasMore=page?.has_more===true;discoveryError=null;
  }catch(error){if(seq===discoveryRequestSeq){discoveryError=error;discoveryHasMore=false;/* Preserve already rendered cards instead of blanking Events. */}}
  finally{if(seq===discoveryRequestSeq){discoveryLoading=false;renderList();}}
}

function eventDiscoveryRecovery(){return `<section class="kx-events-recovery"><div>${icon('refresh',{size:24})}</div><div><strong>La cartelera está volviendo a sincronizarse.</strong><span>Conservamos la navegación y puedes reintentar sin salir de KOMBAX Events.</span></div><button type="button" class="btn btn-primary btn-sm" id="kx-events-retry">Reintentar</button></section>`;}
function renderList({force=false}={}){
  const host=document.getElementById('kx-events-list');if(!host)return;const nextKey=eventDiscoveryRenderKey();if(!force&&host===discoveryRenderHost&&nextKey===discoveryRenderKey)return;discoveryRenderHost=host;discoveryRenderKey=nextKey;const q=filters.query.trim().toLowerCase();
  const list=cached.filter(e=>{const stateOk=!filters.estado||(filters.estado.startsWith('phase:')?e.fase_temporal===filters.estado.slice(6):filters.estado==='inscripciones_abiertas'?registrationStatus(e)==='abiertas':e.estado===filters.estado);return (!filters.tipo||e.tipo===filters.tipo)&&stateOk&&(!q||[e.nombre,e.resumen,e.descripcion,e.organizador_nombre,e.lugar_nombre,e.direccion,e.municipio,e.provincia,e.tickets_proveedor].join(' ').toLowerCase().includes(q));});
  const filtered=Boolean(filters.query.trim()||filters.tipo||filters.estado);
  if(list.length)host.innerHTML=list.map(eventCard).join('');
  else if(discoveryError&&!filtered)host.innerHTML=eventDiscoveryRecovery();
  else host.innerHTML=visualEmpty({filtered});
  host.querySelector('#kx-events-retry')?.addEventListener('click',()=>void loadDiscovery({append:false}));
  host.querySelector('#kx-events-reset-filters')?.addEventListener('click',()=>{resetEventFilters();void loadDiscovery({append:false});});
  host.querySelectorAll('.kx-event-open').forEach(button=>button.addEventListener('click',()=>openEvent(button.dataset.kxEvent)));
  host.querySelectorAll('[data-kx-buy-ticket]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();const item=cached.find(x=>String(x.id)===String(button.dataset.kxBuyTicket));if(item)buyEventTickets(item);}));
  host.querySelectorAll('.kx-event-card-large').forEach(card=>{
    const warm=()=>prefetchEventDetail(card.dataset.kxEvent);
    card.addEventListener('pointerenter',warm,{once:true,passive:true});card.addEventListener('focusin',warm,{once:true});card.addEventListener('pointerdown',warm,{once:true,passive:true});
    card.addEventListener('click',event=>{if(event.target.closest('button,a,input,select,textarea'))return;openEvent(card.dataset.kxEvent)});
    card.addEventListener('keydown',event=>{if(event.target.closest('button,a,input,select,textarea'))return;if(event.key==='Enter'||event.key===' '){event.preventDefault();openEvent(card.dataset.kxEvent);}});
  });
  if(discoveryHasMore&&discoveryCursor){const more=document.createElement('button');more.type='button';more.className='btn btn-ghost kx-events-load-more';more.textContent=discoveryLoading?'Cargando…':'Cargar más eventos';more.disabled=discoveryLoading;more.addEventListener('click',async()=>{more.disabled=true;more.textContent='Cargando…';await loadDiscovery({append:true});});host.appendChild(more);}
}

function resetEventFilters({render=false}={}){filters={query:'',tipo:'',estado:''};const search=document.getElementById('kx-events-query');if(search)search.value='';document.querySelectorAll('[data-kx-state]').forEach(x=>x.classList.toggle('active',x.dataset.kxState===''));document.querySelectorAll('[data-kx-event-type]').forEach(x=>x.classList.toggle('active',x.dataset.kxEventType===''));if(render)renderList();}

function bindOrganizerActions(root=document){
  root.querySelector('#kx-events-create')?.addEventListener('click',()=>openEventEditor());
  root.querySelector('#kx-events-create-unavailable')?.addEventListener('click',()=>openOrganizerPlanGate(organizerContexts[0]));
  root.querySelector('#kx-events-my-events')?.addEventListener('click',()=>void renderMyEventsCenter());
}
function bindInvitationActions(root=document){root.querySelectorAll('[data-kx-invite]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await repos.kombaxEvents.respondInvitation(b.dataset.kxInvite,b.dataset.answer==='1');toast(b.dataset.answer==='1'?'Invitación aceptada.':'Invitación rechazada.');await refreshEventContextData();}catch(error){b.disabled=false;toast(error?.message||'No se pudo responder.','error')}}));}
