      invalidateEventDetail(event.id);batchStatus(pendingCovers?`${uploaded} archivo${uploaded===1?'':'s'} guardado${uploaded===1?'':'s'}. ${pendingCovers} vídeo${pendingCovers===1?'':'s'} necesita${pendingCovers===1?'':'n'} regenerar o elegir portada; puedes hacerlo desde esta misma pantalla.`:`${uploaded} archivo${uploaded===1?'':'s'} añadido${uploaded===1?'':'s'} al álbum. Actualizando la vista…`,pendingCovers?'ready':'success');setTimeout(()=>{closeModal();void openMediaManager(event);},pendingCovers?700:220);
