  wrap.querySelectorAll('[data-kx-reuse-asset]').forEach(button=>button.addEventListener('click',async()=>{const asset=reusableAssets[Number(button.dataset.kxReuseAsset)];if(!asset)return;button.disabled=true;try{await repos.kombaxEvents.addMediaReference(fresh.id,{source_kind:asset.source_kind,source_id:asset.source_id,titulo:asset.titulo,momento:asset.momento});invalidateEventDetail(fresh.id);button.textContent='Ya está en el álbum';toast('Recurso añadido al álbum sin duplicar el archivo físico.');}catch(error){button.disabled=false;toast(error?.message||'No se pudo añadir al álbum.','error')}}));
