function minorEur(value){return eur((Number(value)||0)/100);}
function refundStateLabel(value){return ({not_required:'Sin devolución',refund_pending:'Pendiente',refund_processing:'Procesando',partially_refunded:'Parcialmente reembolsado',refunded:'Reembolsado',refund_failed:'Error en reembolso',manual_review:'Revisión manual'})[String(value||'')]||String(value||'Sin devolución');}
function stripeBalanceEur(rows=[]){const eurRow=(Array.isArray(rows)?rows:[]).find(x=>String(x?.currency||'').toUpperCase()==='EUR');return minorEur(eurRow?.amount||0);}

function eventCenterStateLabel(event={}){return STATE_LABEL[String(event.estado||'')]||String(event.estado||'Borrador');}
function eventCenterTicketingLabel(event={}){if(event.ticketing_active===true&&event.ticketing_enabled===true&&event.ticketing_mode==='kombax')return 'Venta interna configurada';if(event.ticketing_active===true)return 'Servicio autorizado · falta configurar';if(['requested','under_review'].includes(String(event.ticketing_service_status||'')))return 'Solicitud de Ticketing en revisión';if(event.ticketing_mode==='external')return 'Ticketing externo';return 'Ticketing sin solicitar';}
function eventCenterOccupancy(event={}){const cap=Number(event.ticket_capacity||0),paid=Number(event.tickets_paid||0);return cap>0?Math.min(100,Math.max(0,Math.round((paid/cap)*100))):null;}
function eventCenterCard(event={}){const occupancy=eventCenterOccupancy(event),ticketActive=event.ticketing_active===true&&event.ticketing_enabled===true&&event.ticketing_mode==='kombax';return `<article class="kx-my-event-card" data-kx-my-event-card="${esc(event.id||'')}"><div class="kx-my-event-poster"><img src="${esc(poster(event))}" alt="" style="${esc(posterFocusStyle(event))}"><span class="kx-event-card-status ${esc(STATE_CLASS[event.estado]||'draft')}"><i></i>${esc(eventCenterStateLabel(event))}</span></div><div class="kx-my-event-body"><header><div><small>${esc(typeLabel(event.tipo))} · ${esc(rangeLabel(event))}</small><h3>${esc(publicText(event.nombre,'KOMBAX Evento'))}</h3><p>${esc([event.lugar_nombre,event.municipio,event.provincia].filter(Boolean).join(' · ')||'Ubicación por anunciar')}</p></div><span class="kx-market-status ${ticketActive?'ok':'pending'}">${ticketActive?icon('checkCircle',{size:14}):icon('shoppingBag',{size:14})} ${esc(eventCenterTicketingLabel(event))}</span></header><div class="kx-my-event-kpis"><span><small>Vistas · 30 d</small><strong>${Number(event.views_30d||0)}</strong></span><span><small>Entradas pagadas</small><strong>${ticketActive?Number(event.tickets_paid||0):'—'}</strong></span><span><small>Check-in</small><strong>${ticketActive?Number(event.tickets_used||0):'—'}</strong></span><span><small>${occupancy==null?'Ingresos':'Ocupación'}</small><strong>${occupancy==null?(ticketActive?minorEur(event.revenue_minor):'—'):`${occupancy} %`}</strong></span></div><div class="kx-my-event-actions"><button type="button" class="btn btn-primary" data-kx-event-center="${esc(event.id)}">Centro del evento</button><button type="button" class="btn btn-ghost" data-kx-event-builder="${esc(event.id)}">Gestionar evento</button><button type="button" class="btn btn-ghost" data-kx-event-open-managed="${esc(event.id)}">Ver ficha</button></div></div></article>`;}
function eventOpsTool(id,title,detail,{locked=false,reason='',tone='',iconName='activity'}={}){return `<button type="button" class="kx-event-ops-tool ${locked?'locked':''} ${esc(tone)}" data-kx-event-ops-tool="${esc(id)}" ${locked?`data-kx-event-lock="${esc(reason)}"`:''}><span>${locked?icon('lock',{size:19}):icon(iconName,{size:19})}</span><strong>${esc(title)}</strong><small>${esc(detail)}</small></button>`;}

