    const modal=openDetail({title:t('events.results.title'),subtitle:`${publicText(event.nombre,'KOMBAX Evento')} · ${t('events.results.subtitle')}`,width:'1120px',className:'kx-r77-results-modal is-events',body:`<div class="kx-r77-results-toolbar"><button class="btn btn-primary btn-sm" data-r77-result-filter="all">${esc(t('events.results.all'))}</button><button class="btn btn-ghost btn-sm" data-r77-result-filter="completed">${esc(t('events.results.completed'))}</button><button class="btn btn-ghost btn-sm" data-r77-result-filter="pending">${esc(t('events.results.pending'))}</button><button class="btn btn-ghost btn-sm" data-r77-result-filter="cancelled">${esc(t('events.results.cancelled'))}</button><button class="btn btn-ghost btn-sm" id="kx-r77-results-pdf">PDF</button></div><div id="kx-r77-results-body">${render('all')}</div>`});
    modal.wrap.querySelectorAll('[data-r77-result-filter]').forEach(button=>button.addEventListener('click',()=>{modal.wrap.querySelectorAll('[data-r77-result-filter]').forEach(x=>x.className='btn btn-ghost btn-sm');button.className='btn btn-primary btn-sm';modal.wrap.querySelector('#kx-r77-results-body').innerHTML=render(button.dataset.r77ResultFilter);}));
