    const modal=openDetail({title:'Entradas, cobros y acceso',subtitle:publicText(event.nombre,'KOMBAX Evento'),width:'1040px',className:'kx-event-ticket-manager',body:`<section class="kx-ticket-manager-summary"><article><small>SERVICIO BASE</small><strong>KOMBAX Events</strong><span>Publicación de evento</span></article><article><small>TICKETING</small><strong>${esc(addonLabel)}</strong><span>${addon.included_by_plan?'Incluido permanentemente':addonActive?'Activación vigente':'Venta interna bloqueada hasta activación'}</span></article><article><small>CONTRATO</small><strong>${contractsReady?'Aceptado':'Pendiente'}</strong><span>${contracts.length} documento(s) vigente(s)</span></article><article><small>MODO</small><strong>${esc(mode==='kombax'?'Venta KOMBAX':mode==='external'?'Venta externa':'Sin venta')}</strong><span>${esc(eventTicketStatusLabel(ticketStatus({...event,...status})))}</span></article><article><small>VENTAS</small><strong>${Number(status.tickets_paid||0)}</strong><span>${status.tickets_available==null?'Cupo no definido':`${Number(status.tickets_available)} disponibles`}</span></article><article><small>COBROS</small><strong>${esc(stripeReady?'Stripe activo':status.connect_status||'No conectado')}</strong><span>${esc(connectSubjectLabel(sellerType))}</span></article></section>${dashboard?ticketDashboardHtml(dashboard):''}${contractHtml}<div class="alert"><strong>Publicar ≠ Destacar ≠ Ticketing</strong><span><b>KOMBAX Events</b> permite publicar el evento. <b>Destacar</b> aumenta su visibilidad y lo amplifica en KOMBAX Social. <b>Ticketing</b> añade venta interna, ticket QR, lector y control de acceso.</span></div><p class="kx-ticket-manager-note">Ticketing incluye checkout, ticket digital/imprimible, QR, lector y control de puerta. ${addon.included_by_plan&&!largeEvent?'Está incluido en este plan.':largeEvent?'Este evento supera 1.000 entradas: se gestiona como <b>Gran Evento</b> con condiciones específicas.':tierLimit?`Activación aplicable: hasta <b>${tierLimit.toLocaleString(kxLocaleTag(kxGetLocale()))}</b> entradas · <b>${tierPrice.toLocaleString(kxLocaleTag(kxGetLocale()),{minimumFractionDigits:0,maximumFractionDigits:2})} €</b>.`:'Configura el aforo de entradas para calcular la activación.'} KOMBAX no añade gasto fijo por entrada al comprador. Platform fee de este organizador: <b>${platformFee.toLocaleString(kxLocaleTag(kxGetLocale()))} %</b>. El importe facial se procesa para la cuenta Stripe Connect del organizador.</p>`,actions:`${!addonActive&&['not_requested','rejected','cancelled',''].includes(String(addon.status||''))?'<button class="btn btn-showcase" id="kx-ticket-addon-request">Solicitar Events + Ticketing</button>':''}<button class="btn btn-primary" id="kx-ticket-config">Configurar entradas</button>${sellerType&&sellerId?'<button class="btn btn-showcase" id="kx-ticket-payments">Cobros y Stripe</button>':''}${mode==='kombax'&&addonActive&&contractsReady?'<button class="btn btn-ghost" id="kx-ticket-sales">Ventas</button><button class="btn btn-ghost" id="kx-ticket-finance">Finanzas</button><button class="btn btn-ghost" id="kx-ticket-comms">Comunicaciones</button><button class="btn btn-ghost" id="kx-ticket-bi">BI Enterprise</button><button class="btn btn-ghost" id="kx-ticket-scan">Escanear QR</button><button class="btn btn-ghost" id="kx-ticket-access-history">Historial accesos</button><button class="btn btn-ghost" id="kx-ticket-staff">Equipo de acceso</button>':''}`});
