    modal.wrap.querySelector('#kx-ticket-config')?.addEventListener('click',()=>{modal.close();openEventTicketConfigForm(event,{...status,ticketing_mode:mode});});
    modal.wrap.querySelector('#kx-ticket-sales')?.addEventListener('click',()=>openEventTicketSales(event));
    modal.wrap.querySelector('#kx-ticket-finance')?.addEventListener('click',()=>openEventFinance(event));
    modal.wrap.querySelector('#kx-ticket-comms')?.addEventListener('click',()=>openEventCommunications(event));
    modal.wrap.querySelector('#kx-ticket-bi')?.addEventListener('click',()=>openEventBI(event));
