function bindEventManagementMenu(wrap,event){
  const shell=wrap.querySelector('.kx-event-manage-shell'),toggle=wrap.querySelector('#kx-event-manage-toggle'),menu=wrap.querySelector('#kx-event-manage-menu'),scrim=wrap.querySelector('#kx-event-manage-scrim');
  if(!shell||!toggle||!menu)return;
  let keyHandler=null,outsideHandler=null;
  const detach=()=>{if(keyHandler)document.removeEventListener('keydown',keyHandler);if(outsideHandler)document.removeEventListener('pointerdown',outsideHandler);keyHandler=null;outsideHandler=null;};
  const cleanup=()=>{detach();menu.hidden=true;if(scrim)scrim.hidden=true;menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');document.body.classList.remove('kx-event-management-open');};
  const setOpen=open=>{menu.hidden=!open;if(scrim)scrim.hidden=!open;toggle.setAttribute('aria-expanded',open?'true':'false');menu.classList.toggle('open',open);document.body.classList.toggle('kx-event-management-open',open);detach();if(open){keyHandler=e=>{if(e.key==='Escape'){setOpen(false);toggle.focus();}};outsideHandler=e=>{if(!shell.contains(e.target)&&!scrim?.contains(e.target))setOpen(false);};document.addEventListener('keydown',keyHandler);setTimeout(()=>document.addEventListener('pointerdown',outsideHandler),0);}};
  const close=()=>setOpen(false);
  wrap.addEventListener('kx:modal-before-close',cleanup,{once:true});
  toggle.addEventListener('click',()=>setOpen(toggle.getAttribute('aria-expanded')!=='true'));
  wrap.querySelector('#kx-event-manage-close')?.addEventListener('click',close);scrim?.addEventListener('click',close);
  const actions={operations:()=>{closeModal();void renderEventOperationsCenter(event.id,event);},builder:()=>openEventBuilder(event),ticketing:()=>openEventTicketingManager(event),access:()=>openEventAccessScanner(event),edit:()=>openEventEditor(event),visibility:()=>openEventVisibilityManager(event),cover:()=>openEventEditor(event,{visualFirst:true}),participants:()=>openParticipantManager(event),discovery:()=>openKombaxDiscovery({preset:'all',event}),fight:()=>openFightEditor(event),publication:()=>requestEventPublication(event),promote:()=>requestEventPromotion(event),media:()=>openMediaManager(event),partners:()=>openPartnerManager(event),sponsorship:()=>openEventBrandSponsorshipSettings(event),visual:()=>openVisualStudio(event)};
  menu.querySelectorAll('[data-kx-manage]').forEach(button=>button.addEventListener('click',()=>{const fn=actions[button.dataset.kxManage];close();fn?.();}));
}

