  if(feedbackTimer)clearTimeout(feedbackTimer);setEventCardOpening(key,false);if(openSeq!==eventOpenSeq)return;if(feedbackWrap&&!feedbackWrap.isConnected)return;if(!event){openEventRecovery(key,{missing:true});return;}
