  const actions=`<button type="button" class="btn btn-ghost" id="kx-event-interest">${icon('heart',{size:15})} <span data-kx-event-interest-label>${event.engagement?.mi_estado?'Guardado':'Me interesa'}</span></button><button type="button" class="btn btn-ghost" id="kx-event-share">${icon('arrowUpRight',{size:15})} Compartir</button><button type="button" class="btn btn-ghost" id="kx-event-qr">QR</button><button type="button" class="btn btn-ghost" id="kx-event-report">Reportar</button>${ticketAccess?.can_checkin?`<button type="button" class="btn btn-primary" id="kx-event-access-scan">${icon('checkin',{size:15})} Escanear QR</button>`:''}${!event.can_manage?`<button type="button" class="btn btn-ghost" id="kx-event-visual">${icon('sparkles',{size:15})} Visual</button>`:''}`;
  const training=isTrainingEvent(event),acceptedCount=Number(event.participants_accepted_count??participants.filter(x=>x.estado_inscripcion==='aceptada').length);const preparationRows=[];
  const competitionSections=training?'':`${mainEventFeature(heroEvent,fights)}<section id="kx-event-fight-card">${fightsSection(event,fights,media)}</section>`;
  const body=`<div class="kx-event-detail kx-event-detail-large ${training?'kx-event-training-detail':''}"><section class="kx-event-detail-hero kx-event-detail-hero-large"><img src="${esc(poster(event))}" alt="Cartel de ${esc(eventName)}" style="${esc(posterFocusStyle(event))}" data-kx-event-poster-motion data-kx-event-poster-open tabindex="0" role="button" aria-label="Ampliar cartel de ${esc(eventName)}"><div class="kx-event-detail-overlay"></div><div class="kx-event-detail-copy"><div class="kx-event-card-status ${status.klass}"><span></span>${esc(status.label)}</div><span>${esc(typeLabel(event.tipo))}</span><h2>${esc(eventName)}</h2><p>${esc(eventSummary)}</p>${channelPills(event)}<div class="kx-event-detail-facts"><strong>${icon('calendar',{size:16})}${esc(rangeLabel(event))}</strong><strong>${icon('mapPin',{size:16})}${esc(place)}</strong><strong>${icon('users',{size:16})}${acceptedCount} ${training?(acceptedCount===1?'ponente':'ponentes'):'participantes'}</strong></div>${training?'':mainEventTeaser(heroEvent)}</div>${heroOrganizationPanel(heroEvent)}${eventManagementMenu(event)}<div class="kx-event-organization-glow" aria-hidden="true"></div></section>${eventPrimaryCtas(event,{canSubmit})}${eventDetailNav(event,{hasMedia:media.length>0,mediaCount:media.length,canManage:event.can_manage})}${trainingOverview(event,participants)}${eventInfoExperience(event)}${competitionSections}<section id="kx-event-fighters">${participantSection(event,participants,preparationRows)}</section><section id="kx-event-organization">${entities.length?`<section class="kx-event-organizations">${entitySections(entities)}</section>`:`<section class="kx-event-foundation-note"><strong>Organización</strong><p>La organización y los colaboradores aparecerán aquí cuando se confirmen.</p></section>`}</section>${media.length||event.can_manage?`<section id="kx-event-highlights">${mediaSection(event,media)}</section>`:''}<section id="kx-event-community" class="kx-event-community"><div class="loading-card">Cargando comunidad del evento…</div></section><section class="kx-event-viral-strip ${training?'training':''}"><div><span>${training?'FORMACIÓN → PRÁCTICA → ÁLBUM → HISTORIA':'DEL CARTEL A LOS RESULTADOS'}</span><strong>${Number(event.engagement?.interesados||0)+Number(event.engagement?.asistiran||0)} personas siguiendo este evento</strong><p>${training?'Programa, plazas, horarios y contenido visual conviven en una ficha adaptada a formación.':'Sigue las novedades, las entradas y los resultados de este evento desde un mismo lugar.'}</p></div><div class="kx-event-viral-pulse" aria-hidden="true"><i></i><b>${esc(phaseLabel(event.fase_temporal)||'LIVE')}</b></div></section><section class="kx-event-phase-note kx-event-product-note"><span>${training?'FORMACIÓN KOMBAX':'EXPERIENCIA KOMBAX EVENTS'}</span><p>${training?'Seminarios, masterclass y formatos formativos comparten Events con una experiencia adaptada a formación.':'Entradas, inscripción, ubicación, Fight Card, álbum y resultados permanecen unidos en la misma ficha del evento.'}</p></section></div>`;
  const detailOptions={title:eventName,subtitle:`${typeLabel(event.tipo)} · ${rangeLabel(event)}`,body,actions,width:'1240px',className:'kx-event-detail-modal kx-event-detail-modal-large'};const opened=feedbackWrap?.isConnected?replaceEventLoadingWithDetail(feedbackWrap,detailOptions):openDetail(detailOptions);if(!opened)return;const {wrap}=opened;
  wrap.classList.add('kx-event-detail-layer');
  wrap.querySelectorAll('[data-kx-profile]').forEach(b=>b.addEventListener('click',()=>openKombaxPublicProfile(b.dataset.kxProfile)));
  bindFightImageFallbacks(wrap);bindFightCards(wrap,heroEvent,fights);bindEventAlbum(wrap,event,media);bindEventPosterInteractions(wrap,event);wrap.querySelectorAll('[data-kx-album-manage]').forEach(button=>button.addEventListener('click',()=>openMediaManager(event)));bindEventParticipantDetailActions(wrap,event,eventName);
  wrap.querySelectorAll('[data-kx-detail-jump]').forEach(button=>button.addEventListener('click',()=>wrap.querySelector(`#${button.dataset.kxDetailJump}`)?.scrollIntoView({behavior:'smooth',block:'start'})));
