  const {wrap}=openDetail({title:training?'Ponentes e instructores':'Participantes',subtitle:publicText(event.nombre,'KOMBAX Evento'),body,width:'980px',className:'kx-participant-modal'});const host=wrap.querySelector('#kx-participant-admin-list'),more=wrap.querySelector('#kx-event-participant-admin-more'),count=wrap.querySelector('#kx-event-participant-admin-count');
  const refresh=async()=>{invalidateEventDetail(event.id);closeModal();await openParticipantManager(event,{returnToBuilder})};
  const bindAdminActions=()=>{bindFightImageFallbacks(host);host.querySelectorAll('[data-kx-registration-preparation]').forEach(b=>b.addEventListener('click',()=>{closeModal();renderCompetitionPreparation({eventSource:'kombax_event',eventId:fresh.id,registrationId:b.dataset.kxRegistrationPreparation,title:`${publicText(fresh.nombre,'KOMBAX Evento')} · preparación`,onBack:()=>openParticipantManager(fresh,{returnToBuilder})});}));host.querySelectorAll('[data-kx-official-weigh-in]').forEach(b=>b.addEventListener('click',()=>registerOfficialWeighIn({eventSource:'kombax_event',eventId:fresh.id,registrationId:b.dataset.kxOfficialWeighIn,onDone:refresh})));host.querySelectorAll('[data-kx-participant-state]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await repos.kombaxEvents.setParticipantStatus(b.dataset.id,b.dataset.kxParticipantState);toast('Estado actualizado.');await refresh()}catch(error){b.disabled=false;toast(error?.message||'No se pudo actualizar.','error')}}));host.querySelectorAll('[data-kx-participant-edit]').forEach(b=>b.addEventListener('click',()=>{const row=participants.find(x=>String(x.id)===String(b.dataset.kxParticipantEdit));if(row)openParticipantEditor(fresh,row,{returnToBuilder});}));host.querySelectorAll('[data-kx-participant-frame]').forEach(b=>b.addEventListener('click',()=>{const row=participants.find(x=>String(x.id)===String(b.dataset.kxParticipantFrame));if(!row)return;const referenceable=safeExternal(row.foto_url);openMediaFramingEditor({title:`Ajustar imagen · ${row.nombre_publico||'participante'}`,subtitle:'Define el encuadre de esta persona en tarjetas y miniaturas. La foto original se conserva.',src:fighterPhoto(row),initial:row.media_presentation,preset:'fighter',secondaryActionLabel:referenceable?'Añadir también al álbum':'',onSecondaryAction:referenceable?()=>repos.kombaxEvents.addMediaReference(fresh.id,{source_kind:'participant',source_id:row.id,titulo:`${row.nombre_publico||'Participante'} · foto oficial`,momento:'evento'}):null,onSave:async presentation=>{await repos.mediaFraming.set('event_participant',row.id,presentation);row.media_presentation=presentation;invalidateEventDetail(fresh.id);setTimeout(()=>openParticipantManager(fresh,{returnToBuilder}),80);}});}));host.querySelectorAll('[data-kx-participant-album]').forEach(b=>b.addEventListener('click',async()=>{const row=participants.find(x=>String(x.id)===String(b.dataset.kxParticipantAlbum));if(!row)return;b.disabled=true;try{await repos.kombaxEvents.addMediaReference(fresh.id,{source_kind:'participant',source_id:row.id,titulo:`${row.nombre_publico||'Participante'} · foto oficial`,momento:'evento'});invalidateEventDetail(fresh.id);toast('Foto añadida al álbum sin duplicar el archivo.');b.textContent='En el álbum';}catch(error){b.disabled=false;toast(error?.message||'No se pudo añadir al álbum.','error')}}));};
  const paint=meta=>{host.innerHTML=participants.length?participants.map(x=>participantCard(x,{manage:true,preparation:preparationRows.find(r=>String(r.registration_id)===String(x.id))||null})).join(''):`<div class="kx-event-mini-empty"><strong>Sin ${personPlural} todavía.</strong><span>${adminQuery?'Prueba con otra búsqueda.':training?'Añade al profesional que impartirá la sesión.':'Abre inscripciones o añade una ficha pública.'}</span></div>`;count.textContent=`${participants.length} cargados · ${Number(meta?.total_count||0)} totales`;more.hidden=!adminHasMore;bindAdminActions();};
