  const posterPreview=currentPoster?`<article class="kx-fight-card-poster-manager-preview" data-kx-event-media="${esc(currentPoster.id)}" data-kx-media-kind="${esc(currentPoster.tipo)}" data-kx-media-moment="${esc(currentPoster.momento||'previo')}" data-kx-local-media="${esc(currentPoster.local_url||'')}" data-kx-media-presentation="${esc(posterPresentation)}"><div class="kx-event-media-stage"><span class="kx-event-media-loading">Preparando cartelera…</span></div><div><span>ACTUAL</span><strong>${esc(currentPoster.titulo||'Cartelera oficial')}</strong><small>Se muestra en la Fight Card y también permanece en el álbum oficial.</small></div></article>`:`<div class="kx-fight-card-poster-empty">${icon('image',{size:25})}<div><strong>Sin cartel gráfico de cartelera</strong><span>No es obligatorio. Úsalo cuando ya tengas un póster con todas las caras o enfrentamientos.</span></div></div>`;
  const body=`<div class="kx-fight-manager r48-premium"><div class="kx-partner-head kx-fight-manager-head"><span>FIGHT CARD · MAIN · CO-MAIN · UNDERCARD</span><h3>Construye la cartelera como una velada profesional.</h3><p>Las fotos individuales mejoran cada tarjeta, pero nunca son obligatorias. También puedes subir un cartel completo con todas las caras y mantener los combates estructurados debajo.</p></div><div class="kx-builder-inline-stats"><span><b>${acceptedCount}</b> participantes</span><span><b>${fights.length}</b>/30 combates</span><span class="main"><b>${fights.filter(x=>strictFlag(x.destacado)).length}</b> Main Event</span><span class="co"><b>${fights.filter(x=>strictFlag(x.co_estelar)).length}</b> Co-Main</span></div><section class="kx-fight-card-poster-manager"><div class="kx-fight-card-poster-manager-head"><div><span>${icon('image',{size:15})} CARTEL GENERAL DE LA VELADA</span><strong>¿Ya tienes el póster con todos los peleadores?</strong><p>Súbelo aquí. KOMBAX lo trata como cartelera oficial, lo muestra ampliable y conserva la Fight Card estructurada para horarios y resultados.</p></div><label class="btn btn-ghost" for="kx-fight-card-poster-input">${icon('plus',{size:14})} ${currentPoster?'Sustituir cartel':'Subir cartel'}</label><input id="kx-fight-card-poster-input" type="file" accept="image/jpeg,image/png,image/webp" hidden></div>${posterPreview}<div class="kx-fight-card-poster-manager-actions"><button type="button" class="btn btn-primary" id="kx-fight-card-poster-save" disabled>Guardar cartelera oficial</button>${currentPoster?'<button type="button" class="btn btn-ghost" id="kx-fight-card-poster-remove">Retirar cartel actual</button>':''}<span id="kx-fight-card-poster-status" aria-live="polite">JPG, PNG o WEBP · se optimiza antes de subir.</span></div></section>${fights.length?`<div class="kx-fight-manager-list">${fights.map(f=>`<article class="kx-fight-manager-row ${strictFlag(f.destacado)?'main':strictFlag(f.co_estelar)?'co':''}">${fightCard(f,{compact:true})}<div class="kx-fight-manager-actions"><button type="button" class="btn btn-ghost btn-sm" data-kx-fight-edit="${esc(f.id)}">Editar / horario · jerarquía</button><button type="button" class="btn btn-ghost btn-sm" data-kx-fight-remove="${esc(f.id)}">Eliminar</button></div></article>`).join('')}</div>`:`<div class="kx-event-mini-empty"><strong>Todavía no hay combates estructurados.</strong><span>Puedes subir primero el cartel gráfico, pero añade después los combates para horarios, resultados y navegación.</span></div>`}<div class="kx-fight-manager-footer"><button type="button" class="btn btn-primary" id="kx-manager-add-fight" ${acceptedCount<2?'disabled':''}>${icon('fighter',{size:15})} Añadir combate</button><button type="button" class="btn btn-ghost" id="kx-manager-add-participants">Gestionar participantes y fotos</button><button type="button" class="btn btn-ghost" id="kx-manager-find-fighter">${icon('search',{size:15})} Buscar sustituto / rival</button>${returnToBuilder?'<button type="button" class="btn btn-ghost" id="kx-manager-back-builder">Volver al constructor</button>':''}</div></div>`;
  const {wrap}=openDetail({title:'Fight Card del evento',subtitle:publicText(fresh.nombre,'KOMBAX Evento'),body,width:'1180px',className:'kx-fight-manager-modal kx-r48-premium-modal'});
  bindFightImageFallbacks(wrap);bindFightCards(wrap,{...fresh,can_manage:true},fights);await hydrateEventMedia(wrap);
  const posterInput=wrap.querySelector('#kx-fight-card-poster-input'),posterSave=wrap.querySelector('#kx-fight-card-poster-save'),posterStatus=wrap.querySelector('#kx-fight-card-poster-status');
  posterInput?.addEventListener('change',()=>{const file=posterInput.files?.[0]||null;if(posterSave)posterSave.disabled=!file;if(posterStatus)posterStatus.textContent=file?`${file.name} · listo para optimizar y subir.`:'JPG, PNG o WEBP · se optimiza antes de subir.';});
  posterSave?.addEventListener('click',async()=>{const file=posterInput?.files?.[0];if(!file)return;posterSave.disabled=true;if(posterStatus)posterStatus.textContent='Optimizando y subiendo cartelera…';try{const uploaded=await repos.kombaxEvents.uploadMedia(fresh.id,file,{tipo:'foto',momento:'previo',titulo:`Cartelera oficial · ${publicText(fresh.nombre,'KOMBAX Evento')}`,descripcion:`${FIGHT_CARD_POSTER_MARKER} Cartel gráfico completo de la velada.`,destacado:true,orden:0,estado:'visible'});for(const oldPoster of posters){if(String(oldPoster.id)!==String(uploaded?.id||uploaded?.data?.id||''))await repos.kombaxEvents.removeMedia(oldPoster).catch(()=>{});}invalidateEventDetail(fresh.id);toast('Cartelera oficial actualizada.');setTimeout(()=>openFightCardManager(fresh,{returnToBuilder}),140);}catch(error){posterSave.disabled=false;if(posterStatus)posterStatus.textContent='No se pudo guardar el cartel.';toast(error?.message||'No se pudo subir la cartelera oficial.','error');}});
  wrap.querySelector('#kx-fight-card-poster-remove')?.addEventListener('click',async buttonEvent=>{if(!currentPoster)return;if(!confirm('¿Retirar el cartel gráfico de la cartelera? Los combates estructurados no se eliminan.'))return;const button=buttonEvent.currentTarget;button.disabled=true;try{await repos.kombaxEvents.removeMedia(currentPoster);invalidateEventDetail(fresh.id);toast('Cartel gráfico retirado.');setTimeout(()=>openFightCardManager(fresh,{returnToBuilder}),120);}catch(error){button.disabled=false;toast(error?.message||'No se pudo retirar el cartel.','error');}});
