  const steps=[
    builderStep({id:'base',index:1,title:'Ficha e información',desc:training?'Nombre, tipo, fecha, lugar, descripción, acceso e inscripción de la formación.':'Nombre, tipo, fechas, recinto, inscripción, entradas y publicación.',state:baseDone?'Configurada':'Completar',done:baseDone,action:'Editar ficha'}),
    builderStep({id:'cover',index:2,title:'Portada y banner',desc:'Sube cartel/banner y ajusta el encuadre visual sin salir del flujo.',state:coverDone?'Imágenes listas':'Añadir imágenes',done:coverDone,action:'Portada / encuadre'}),
    builderStep({id:'organization',index:3,title:'Organización',desc:'Organizador, federación avaladora, colaboradores y patrocinadores.',state:`${entities.length} entidad${entities.length===1?'':'es'}`,done:orgDone,action:'Gestionar'}),
    builderStep({id:'participants',index:4,title:training?'Ponentes e instructores':'Participantes y fotos',desc:training?'Añade profesionales KOMBAX o externos, define especialidad y ajusta sus fotografías.':'Añade competidores KOMBAX o externos, sube o reemplaza sus fotos públicas.',state:`${acceptedCount} confirmado${acceptedCount===1?'':'s'}`,done:peopleDone,action:training?'Ponentes':'Participantes'}),
    ...(!training?[builderStep({id:'fights',index:5,title:'Main · Co-Main · Fight Card',desc:'Fight Card y horarios: define estelar y coestelar, ordena combates, asigna horarios y añade un cartel gráfico completo si ya lo tienes.',state:`${fights.length} combate${fights.length===1?'':'s'}${hasFightCardPoster?' · cartel listo':''}`,done:fightsDone,action:'Diseñar cartelera'})]:[]),
    builderStep({id:'album',index:training?5:6,title:'Álbum y multimedia',desc:training?'Publica material previo y fotografías de la sesión con miniaturas ajustables.':'Sube fotos y vídeos, clasifica previo/evento/postevento y vincula material a combates.',state:`${photos}/30 fotos · ${videos}/5 vídeos`,done:albumDone,action:'Abrir álbum'})
  ].join('');
  const ready=training?peopleDone:(fightsDone&&peopleDone);
