  const {wrap}=openDetail({title:'Constructor del evento',subtitle:`${training?'Formación':'Competición'} · Clubes y federaciones autorizadas · mismo dominio KOMBAX Events`,body,width:'1180px',className:'kx-event-builder-modal'});
